            bullets=['مسئله، روش و منابع را روشن بنویسید.', 'قالب گروه آموزشی خودتان بر نمونه اینترنتی مقدم است.', 'فایل حق\u200cنشر دیگران اینجا برای دانلود گذاشته نمی\u200cشود.'],
