            bullets=['رتبه\u200cبندی ملی راحت\u200cترین ارشد وجود ندارد.', 'داوطلب به ظرفیت، همپوشانی درس، زبان و علاقه را بسنجید.', 'علوم و بهداشت را در یک فهرست آسان ادغام نکنید.'],
